    getPlayerInventory: {
        parameters: {
            query?: {
                /**
                 * @description Only answer about this item key. The list then has one entry or none.
                 * @example gold-helmet-trim
                 */
                item?: string;
            };
            header?: never;
            path: {
                /**
                 * @description The League, as it appears in its Heir address: its vanity name (`heir.gg/nacl`) or its Discord server ID.
                 * @example nacl
                 */
                league: string;
                /**
                 * @description Which kind of game account the identifier is. Use a key from the League's `items` call: `mordhau` for a Mordhau PlayFab ID, `steam` for a SteamID64.
                 * @example mordhau
                 */
                credential: string;
                /**
                 * @description The player's game account ID, in the credential's format. Letter case does not matter for a PlayFab ID.
                 * @example A1B2C3D4E5F67890
                 */
                identifier: string;
            };
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description The player's held items. An empty list is a normal answer. */
            200: {
                headers: {
                    /**
                     * @description Answers may be cached for 60 seconds.
                     * @example public, max-age=60, stale-while-revalidate=60
                     */
                    "Cache-Control"?: string;
                    /** @description Send it back as `If-None-Match` to get `304 Not Modified` when nothing changed. */
                    ETag?: string;
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "items": [
                     *         {
                     *           "key": "gold-helmet-trim",
                     *           "name": "Gold helmet trim",
                     *           "expiresAt": null,
                     *           "edition": {
                     *             "number": 3,
                     *             "size": 10
                     *           },
                     *           "imageUrl": "https://media.heir.gg/img/2f6c1c1e-8a0b-4d0f-9d57-0c6e8f1a2b3c/9f2c4e6a8b0d1f3a/sm.webp"
                     *         }
                     *       ]
                     *     }
                     */
                    "application/json": components["schemas"]["InventoryResponse"];
                };
            };
            /** @description Nothing changed since the `ETag` you sent. */
            304: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description The credential is not one this League's game uses, or the identifier is not in that credential's format. */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "error": "invalid-identifier",
                     *       "message": "A PlayFab ID is 14-16 characters using only 0-9 and A-F."
                     *     }
                     */
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description The Authorization header is not a valid League developer key. Send a valid key, or no Authorization header to read without one. */
            401: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "error": "unauthorized",
                     *       "message": "Send a valid League developer key as Authorization: Bearer <key>, or send no Authorization header."
                     *     }
                     */
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description The developer key belongs to another League. A key reads only its own League. */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "error": "forbidden",
                     *       "message": "This key belongs to another League. Send it only to its own League, or send no key."
                     *     }
                     */
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description There is no public inventory at that address. The League does not exist, is not on a plan that includes the API, or has its shop turned off. All three look the same. */
            404: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "error": "league-not-found",
                     *       "message": "No League with a public inventory was found at that address."
                     *     }
                     */
                    "application/json": components["schemas"]["Error"];
                };
            };
            /** @description Too many requests in the last minute: 120 from one address without a key, or the key's plan allowance with one. Wait and try again; cache answers for a minute instead of asking on every event. */
            429: {
                headers: {
                    /**
                     * @description Seconds to wait before retrying.
                     * @example 60
                     */
                    "Retry-After"?: number;
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "error": "rate-limited",
                     *       "message": "Requests without a key are limited to 120 a minute from one address. Try again in a minute, or send a League developer key."
                     *     }
                     */
                    "application/json": components["schemas"]["Error"];
                };
            };
        };
    };
